// Small UI helpers. Nothing here stores or sends data.
$(document).on("shiny:connected", function () {
  Shiny.addCustomMessageHandler("scroll_to", function (id) {
    setTimeout(function () {
      var el = document.getElementById(id);
      if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
    }, 150);
  });

  // Highlight unanswered items/fields; jump to the first one.
  Shiny.addCustomMessageHandler("mark_missing", function (msg) {
    $(".tipi-item").removeClass("missing");
    $(".field-missing").removeClass("field-missing");
    var items = msg.items || [], fields = msg.fields || [];
    items.forEach(function (id) { $("#" + id).addClass("missing"); });
    fields.forEach(function (id) { $("#" + id).closest(".form-group").addClass("field-missing"); });
    var first = fields.length ? document.getElementById(fields[0]) :
                items.length ? document.getElementById(items[0]) : null;
    if (first) first.scrollIntoView({ behavior: "smooth", block: "center" });
  });
});

// Clear the highlight as soon as something is answered.
$(document).on("change", ".tipi-item input", function () {
  $(this).closest(".tipi-item").removeClass("missing");
});
$(document).on("change", "#age, #gender", function () {
  $(this).closest(".form-group").removeClass("field-missing");
});

/* TIPI app styles. System fonts only: no external font or CDN requests. */
:root {
  --accent: #1f5f99;
  --accent-soft: #e7f0f9;
  --ink: #1d2433;
  --muted: #5b6475;
  --line: #d9dee7;
  --bg: #f5f6f8;
  --card: #ffffff;
  --warn: #a8261b;
  --warn-soft: #fdf0ee;
}

html, body {
  background: var(--bg);
  color: var(--ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 16px;
  line-height: 1.55;
}
.container-fluid { padding: 0; }
.wrap { max-width: 760px; margin: 0 auto; padding: 28px 16px 56px; }

h1 { font-size: 2rem; font-weight: 750; line-height: 1.2; margin: 4px 0 10px; letter-spacing: -0.01em; }
h2 { font-size: 1.3rem; font-weight: 700; margin: 0 0 12px; }
h3 { font-size: 1.1rem; font-weight: 700; margin: 26px 0 8px; }
.eyebrow { color: var(--accent); font-weight: 650; font-size: .85rem; letter-spacing: .04em; text-transform: uppercase; margin: 0; }
.lede { font-size: 1.1rem; color: var(--muted); margin: 0 0 6px; max-width: 62ch; }
.help { color: var(--muted); }
.small { font-size: .88rem; }
.center { text-align: center; }

.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 22px 22px 18px;
  margin: 18px 0;
}
.privacy { background: var(--accent-soft); border-color: #c5d8ec; }
.privacy ul { margin: 0; padding-left: 1.2em; }
.privacy li { margin: 6px 0; }

/* About you */
.two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 0 16px; }
.two-col .form-group { margin-bottom: 8px; }
.form-control { height: 42px; font-size: 1rem; border-radius: 8px; border-color: #b8c1cf; }
.control-label { font-weight: 650; }
.field-missing select { border-color: var(--warn); background: var(--warn-soft); }

/* Rating legend */
.legend { list-style: none; padding: 0; margin: 14px 0 6px; display: grid; max-width: 480px;
  grid-template-columns: repeat(7, 1fr); gap: 6px; font-size: .8rem; color: var(--muted); }
.legend li { text-align: center; line-height: 1.25; }
.legend b { display: block; color: var(--ink); font-size: .95rem; }
.stem { font-weight: 700; margin: 18px 0 2px; }

/* Items */
.tipi-item { padding: 14px 10px; margin: 0 -10px; border-top: 1px solid var(--line); border-radius: 8px; }
.tipi-item .form-group { margin: 0; }
.tipi-item .control-label { display: block; font-size: 1.05rem; font-weight: 650; margin-bottom: 10px; }
.tipi-item .shiny-options-group { display: grid; grid-template-columns: repeat(7, 1fr); gap: 6px; max-width: 480px; }
.tipi-item .radio-inline { position: relative; display: block; margin: 0 !important; padding: 0; text-align: center; }
.tipi-item input[type="radio"] { position: absolute; opacity: 0; width: 1px; height: 1px; margin: 0; left: 50%; top: 50%; }
.tipi-item .dot {
  display: flex; align-items: center; justify-content: center;
  height: 44px; border: 1.5px solid #b8c1cf; border-radius: 8px;
  background: #fff; font-weight: 650; cursor: pointer; user-select: none;
  transition: background .12s, border-color .12s, color .12s;
}
.tipi-item .dot:hover { border-color: var(--accent); }
.tipi-item input:checked + span .dot { background: var(--accent); border-color: var(--accent); color: #fff; }
.tipi-item input:focus-visible + span .dot { outline: 3px solid #8db8e6; outline-offset: 2px; }
.tipi-item .ends { display: flex; justify-content: space-between; max-width: 480px;
  font-size: .78rem; color: var(--muted); margin-top: 4px; }
.tipi-item.missing { background: var(--warn-soft); box-shadow: inset 3px 0 0 var(--warn); }

.actions { margin-top: 22px; }
.btn { border-radius: 8px; }
.btn-primary { background: var(--accent); border-color: var(--accent); }
.btn-primary:hover, .btn-primary:focus { background: #184d7d; border-color: #184d7d; }
.btn-lg { padding: 11px 22px; font-weight: 650; }
.alert-box { margin-top: 14px; padding: 10px 14px; border-radius: 8px;
  background: var(--warn-soft); color: var(--warn); border: 1px solid #f0c6c0; font-weight: 600; }

/* Results */
.results .group { font-size: 1.02rem; }
.radar-box { max-width: 600px; margin: 8px auto 0; }
.shiny-plot-output img { max-width: 100%; }
.res-table { width: 100%; border-collapse: collapse; margin: 18px 0 8px; font-size: .95rem; }
.res-table th, .res-table td { padding: 9px 8px; border-bottom: 1px solid var(--line); vertical-align: top; text-align: left; }
.res-table thead th { font-size: .82rem; color: var(--muted); font-weight: 650; border-bottom: 2px solid var(--line); }
.res-table .num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.res-table .strong { font-weight: 700; color: var(--accent); }
.res-table td.band-col { white-space: nowrap; }
.res-table .meaning { font-weight: 400; font-size: .8rem; color: var(--muted); margin-top: 2px; }
details { margin-top: 18px; border-top: 1px solid var(--line); padding-top: 12px; }
summary { cursor: pointer; font-weight: 650; color: var(--accent); }
details li { margin: 6px 0; }

.about p, .about li { font-size: .92rem; }
.about a { color: var(--accent); }
.refs { list-style: none; padding: 0; margin: 0; }
.refs li { padding-left: 2em; text-indent: -2em; margin: 6px 0; overflow-wrap: anywhere; }

footer { text-align: center; color: var(--muted); font-size: .85rem; margin-top: 28px; }

@media (max-width: 560px) {
  h1 { font-size: 1.65rem; }
  .card { padding: 18px 14px 14px; }
  .two-col { grid-template-columns: 1fr; }
  .legend { grid-template-columns: 1fr; gap: 2px; text-align: left; }
  .legend li { text-align: left; }
  .legend b { display: inline-block; width: 1.4em; }
  .tipi-item .shiny-options-group { gap: 4px; }
  .res-table { font-size: .88rem; }
  .res-table th, .res-table td { padding: 8px 4px; }
  .res-table thead th { font-size: .74rem; white-space: normal; }
  .res-table tbody th { word-break: break-word; }
  .res-table .band-col { display: none; }
}
